TEST(MacroFunctions, FRIBIDI_TEST_BITS) {
    binary([](auto x, auto mask) {
        static_assert(std::is_same_v<decltype(FRIBIDI_TEST_BITS(x, mask)), decltype((m::FRIBIDI_TEST_BITS)(x, mask))>);
        EXPECT_EQ(FRIBIDI_TEST_BITS(x, mask), (m::FRIBIDI_TEST_BITS)(x, mask));
    });
}
