TEST(MacroFunctions, FRIBIDI_SET_BITS) {
    binary([](auto x, auto mask) {
        auto a = x, b = x;
        static_assert(std::is_same_v<decltype(FRIBIDI_SET_BITS(a, mask)), decltype((m::FRIBIDI_SET_BITS)(b, mask))>);
        decltype(auto) raw = FRIBIDI_SET_BITS(a, mask);
        decltype(auto) mapped = (m::FRIBIDI_SET_BITS)(b, mask);
        EXPECT_EQ(raw, mapped);
        EXPECT_EQ(a, b);
        EXPECT_EQ(&raw, &a);  // the macro's lvalue: the argument itself
        EXPECT_EQ(&mapped, &b);
    });
}
